/**
 * i18n.mjs — report language dictionary (en / zh).
 *
 * Single source of truth for all user-visible copy that is NOT generated by the
 * LLM agents (chapter scaffolding, score-table labels, degraded banner, chart
 * source prefix, disclaimer). Agent-produced prose follows the report `lang`
 * via the agent contracts; this module covers the deterministic UI strings.
 *
 * Default language is "en" (English). Pass `lang: "zh"` for Chinese reports.
 *
 * Usage:
 *   import { t, DEFAULT_LANG, SUPPORTED_LANGS } from "./lib/i18n.mjs";
 *   t("chartSourceLabel", "en")   // → "Source: "
 *   t("chartSourceLabel", "zh")   // → "数据来源："
 *   t("chartSourceLabel")         // → "Source: " (default en)
 */

