/**
 * Look up a localized string.
 *
 * Fails closed on an unsupported lang (throws), consistent with validateLang().
 * An earlier version silently fell back to DEFAULT_LANG via `??` — that masked
 * typos like `lang: "eng"` rendering the whole report in the wrong language
 * instead of failing loudly. validateLang() at the CLI boundary is the primary
 * guard; t() throwing is the belt-and-suspenders for in-pipeline callers.
 *
 * @param {string} key - dictionary key (see DICT above)
 * @param {string} [lang] - "en" | "zh"; defaults to DEFAULT_LANG
 * @returns {string|string[]} the localized value (string for most keys, array for default*)
 * @throws {Error} if key is unknown or lang is not in SUPPORTED_LANGS
 */
export function t(key, lang = DEFAULT_LANG) {
  const entry = DICT[key];
  if (!entry) throw new Error(`i18n: unknown key "${key}"`);
  if (!SUPPORTED_LANGS.includes(lang)) {
    throw new Error(`i18n: unsupported lang "${lang}" (supported: ${SUPPORTED_LANGS.join(", ")})`);
  }
  const val = entry[lang];
  if (val === undefined) {
    throw new Error(`i18n: key "${key}" has no "${lang}" translation`);
  }
  return val;
}

/**
 * Validate a lang code; throw on unsupported value (fail-closed).
 * @param {string} lang
 * @returns {string} the validated lang (or DEFAULT_LANG if nullish)
 */
export function validateLang(lang) {
  if (lang == null) return DEFAULT_LANG;
  if (!SUPPORTED_LANGS.includes(lang)) {
    throw new Error(`i18n: unsupported lang "${lang}" (supported: ${SUPPORTED_LANGS.join(", ")})`);
  }
  return lang;
}
